import sys
import sqlite3
import xml.etree.ElementTree as ET
import csv
from datetime import datetime

def parse_config(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        config = {}
        for child in root:
            if child.tag == 'database':
                config['database'] = child.attrib['path']
            elif child.tag == 'table':
                config['table'] = child.attrib['name']
                config['columns'] = [col.strip() for col in child.attrib['columns'].split(',')]
        return config
    except Exception as e:
        print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} [ERROR] Failed to parse config: {str(e)}")
