import sys
import sqlite3
from xml.etree import ElementTree as ET
from datetime import datetime

def parse_config(xml_file):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        config = {}
        for child in root:
            if child.tag == 'database':
                config['path'] = child.attrib.get('path')
            elif child.tag == 'table':
                config['name'] = child.attrib.get('name')
                config['columns'] = child.attrib.get('columns').split(',')
        return config
    except Exception as e:
        print(f"[ERROR] {str(e)}", file=sys.stderr)
        sys.exit(1)

def export_data(db_path, table_name, columns):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(f"SELECT {', '.join(columns)} FROM {table_name}")
        rows = cursor.fetchall()
        conn.close()

        if not rows:
            print("No data to export.", file=sys.stderr)
            return

        # Prepare CSV output
        with open(sys.argv[2], 'w') as f:
            # Write header
            f.write(','.join(columns) + '\n')
            # Write data rows
            for row in rows:
                f.write(','.join(str(item) for item in row) + '\n')
    except Exception as e:
        print(f"[ERROR] {str(e)}", file=sys.stderr)
        sys.exit(1)

def main():
    if len(sys.argv) != 3:
        print("Usage: python export_report.py <config.xml> <output.csv>", file=sys.stderr)
        sys.exit(1)

    config = parse_config(sys.argv[1])
    if not config:
        sys.exit(1)

    log_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{log_time} [INFO] config", file=sys.stderr)

    export_data(config['path'], config['name'], config['columns'])

    print(f"{log_time} [INFO] query", file=sys.stderr)
    print(f"{log_time} [INFO] done", file=sys.stderr)

if __name__ == "__main__":
    main()
